python3 -c "
with open('/app/output/final_report.html', 'r') as f:
    html = f.read()
# Check for common issues
issues = []
if '<img src=\"data:image/png;base64,' not in html:
    issues.append('No base64 images found')
else:
    count = html.count('data:image/png;base64,')
    issues.append(f'{count} base64 charts embedded')

# Check sections
for s in ['Dataset Overview', 'White vs. Black', 'Rating Dynamics', 'Opening Analysis', 'Time Control Patterns', 'Key Findings']:
    if s not in html:
        issues.append(f'Missing section: {s}')
    else:
        issues.append(f'Section found: {s}')

# Check file completeness
if html.strip().endswith('</html>'):
    issues.append('HTML properly closed')
else:
    issues.append('HTML not properly closed')

for i in issues:
    print(f'  {\"✓\" if \"Missing\" not in i and \"not properly\" not in i else \"✗\"} {i}')

# Check for any unrendered Python format strings
import re
placeholders = re.findall(r'\{[^}]*:[^}]*\}', html)
if placeholders:
    print(f'  ✗ Unrendered format strings: {placeholders[:5]}')
else:
    print('  ✓ No unrendered format strings')

# Check for empty values
empties = re.findall(r'>%<|>NaN<|>nan<|>None<|>null<', html)
if empties:
    print(f'  ✗ Found empty/null values: {empties[:5]}')
else:
    print('  ✓ No empty/null values')
"

